char buf[2][128];
struct iovec iov[2];
struct mmsghdr msgs[2];
struct timespec timeout = { .tv_sec = 5, .tv_nsec = 0 };
int fd = 4;
int count;

// Link buffers to vectors
iov[0].iov_base = buf[0]; iov[0].iov_len = 128;
iov[1].iov_base = buf[1]; iov[1].iov_len = 128;

// Link vectors to message headers
msgs[0].msg_hdr.msg_iov = &iov[0];
msgs[0].msg_hdr.msg_iovlen = 1;
msgs[1].msg_hdr.msg_iov = &iov[1];
msgs[1].msg_hdr.msg_iovlen = 1;

// Receive up to 2 messages, waiting 5 seconds
count = recvmmsg(fd, msgs, 2, MSG_WAITFORONE, &timeout);
// The received length is stored in msgs[i].msg_len
// If timeout is NULL, it blocks indefinitely.
